var V = MK.frame({box:[40,26,600,330], x:[-6.6,6.6], y:[-1.7,1.7], grid:true, axes:true, title:'y = sin x 与 y = cos x', desc:'周期 2π，值域 [−1,1]'});
document.getElementById("fig").appendChild(V.svg);
V.plot(function(x){return Math.sin(x);}, {color:'blue', w:2.2});
V.plot(function(x){return Math.cos(x);}, {color:'coral', w:2.2});
V.dot([Math.PI/2,1],{color:'blue',r:3.5});
V.dot([0,1],{color:'coral',r:3.5});
V.label([Math.PI/2,1],'sin 峰值 (π/2, 1)',{dx:6,dy:-14,color:'blue',size:12});
V.label([0,1],'cos 峰值 (0, 1)',{dx:-70,dy:-14,color:'coral',size:12});

var V = MK.frame({box:[40,26,600,330], x:[-6.6,6.6], y:[-1.7,1.7], grid:true, axes:true, title:'y = sin x 与 y = cos x', desc:'cos x = sin(x + π/2)：余弦曲线由正弦曲线左移 π/2 得到'});
document.getElementById("fig").appendChild(V.svg);
V.plot(function(x){ return Math.sin(x); }, {color:'blue', w:2.2});
V.plot(function(x){ return Math.cos(x); }, {color:'coral', w:2.2});
V.arrow([Math.PI/2,1],[0.12,1], {color:'amber', w:1.6});
V.label([Math.PI/4,1], '左移 π/2', {dx:0, dy:-14, color:'amber', size:12});
V.dot([Math.PI/2,1], {color:'blue', r:3.5});
V.dot([0,1], {color:'coral', r:3.5});
V.label([3.6,0.85], 'y = sin x', {dx:0, dy:0, color:'blue', size:13});
V.label([3.6,-0.6], 'y = cos x', {dx:0, dy:0, color:'coral', size:13});

var V = MK.frame({box:[40,26,600,330], x:[-6.6,6.6], y:[-4,4], grid:true, axes:true, title:'y = tan x', desc:'周期 π，在 x = π/2 + kπ 处有垂直渐近线'});
document.getElementById("fig").appendChild(V.svg);
V.plot(function(x){ return Math.tan(x); }, {color:'teal', w:2.2});
var a = [Math.PI/2, -Math.PI/2, 3*Math.PI/2, -3*Math.PI/2];
for (var i=0;i<a.length;i++){ V.seg([a[i],-4],[a[i],4],{color:'gray', w:1}); }
V.label([Math.PI/2,-3.4],'x = π/2',{dx:6,dy:0,color:'gray',size:11});
V.label([3*Math.PI/2,-3.4],'x = 3π/2',{dx:6,dy:0,color:'gray',size:11});

var V = MK.frame({box:[40,26,600,330], x:[-1.7,1.7], y:[-1.6,1.6], equal:true, grid:false, axes:true, title:'单位圆上的正弦线与余弦线', desc:'P = (cos θ, sin θ)'});
document.getElementById("fig").appendChild(V.svg);
V.circle([0,0],1,{color:'blue', w:2});
var t = Math.PI/3;
var P = [Math.cos(t), Math.sin(t)];
V.seg([0,0],P,{color:'gray', w:1.4});
V.seg([P[0],0],P,{color:'coral', w:2.4});
V.seg([0,0],[P[0],0],{color:'teal', w:2.4});
V.arc([0,0],0.3,0,t,{color:'amber', w:1.6});
V.dot(P,{color:'blue',r:4});
V.dot([0,0],{color:'gray',r:3});
V.label(P,'P',{dx:8,dy:-6,color:'blue',size:13});
V.label([0.36,0.12],'θ',{dx:0,dy:0,color:'amber',size:12});
V.label([P[0]+0.06, P[1]/2],'sin θ',{dx:8,dy:0,color:'coral',size:12});
V.label([P[0]/2,-0.16],'cos θ',{dx:-10,dy:10,color:'teal',size:12});

