pres.full:
var V = MK.frame({box:[40,26,600,330], x:[-1.7,1.7], y:[-1.55,1.55], equal:true, grid:false, axes:true, title:'单位圆上的正弦线与余弦线', desc:'P = (cos θ, sin θ)'});
document.getElementById("fig").appendChild(V.svg);
V.circle([0,0],1, {color:'blue', w:2});
var t = Math.PI/3;
var P = [Math.cos(t), Math.sin(t)];
V.seg([0,0], P, {color:'gray', w:1.4});
V.seg([P[0],0], P, {color:'coral', w:2.6});
V.seg([0,0], [P[0],0], {color:'teal', w:2.6});
V.arc([0,0], 0.32, 0, t, {color:'amber', w:1.6});
V.dot(P, {color:'blue', r:4});
V.dot([0,0], {color:'gray', r:3});
V.label(P, 'P', {dx:9, dy:-8, color:'blue', size:13});
V.label([0.30,0.14], 'θ', {dx:0, dy:0, color:'amber', size:12});
V.label([P[0], P[1]/2], 'sin θ', {dx:10, dy:0, color:'coral', size:12});
V.label([P[0]/2, -0.18], 'cos θ', {dx:-14, dy:12, color:'teal', size:12});
